def forward(groups):
    parts = groups[0].split('.')
    packed = (int(parts[0]) << 24) | (int(parts[1]) << 16) | (int(parts[2]) << 8) | int(parts[3])
    return {'stored': [packed], 'layout': []}

def inverse(record):
    packed = record['stored'][0]
    return f'{(packed >> 24) & 255}.{(packed >> 16) & 255}.{(packed >> 8) & 255}.{packed & 255}'
